# Expected values generated by test/scipy/gen_stats_final_mgc.py (scipy 1.18.1).
import numpy as np
import scipy.stats as st

@test
def test_mgc():
    x = np.array([0.08564916714362436, 0.09412864224039919, 0.11367201992140341, 0.15973891463707857, 0.2368105065960997, 0.28420116374879145, 0.2927207490124871, 0.39122819049566204, 0.4306280204141778, 0.4331269402364738, 0.479051298140834, 0.5167401826213637, 0.5821620360643678, 0.5867985714381407, 0.648547207079825, 0.6962159966701554, 0.7345771514092145, 0.7378377872921602, 0.8012744652063969, 0.9562672548360985])
    y = np.array([0.007410284007838311, 0.0575332150283417, 0.027841389263855716, 0.041215820951148716, 0.10066476955655924, 0.11002844847071278, 0.10925092016152305, 0.19172334752095083, 0.1869577923489571, 0.2229472011413911, 0.2482023379243418, 0.2715630520107732, 0.371937639606005, 0.3909057561789105, 0.43097303821509153, 0.5162212240086851, 0.5545117459053472, 0.5814924343596576, 0.6781490089989033, 0.925382833900208])
    r = st.multiscale_graphcorr(x, y, reps=200, random_state=1)
    assert abs(r.statistic - 1.0) < 1e-9
    assert abs(r.pvalue - 0.004975124378109453) < 1e-12
    assert abs(float(np.sum(r.mgc_map)) - 312.535559186088) < 1e-7
    assert r.mgc_map.shape == (20, 20)
    assert list(r.opt_scale) == [7, 5]
